var n=`0495-halawet-el-jibn`;var t=`world-0495`;var a=`SY`;var s=`western-asia`;var o=8;var r=44;var l={en:`Halawet el Jibn`,ua:`Халавет ель джібн`};var d={en:`A traditional dish from Syria, centered on semolina flour, mozzarella, heavy cream, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: семоліна, моцарела, вершки високої жирності, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`semolina-flour`,220,`g`],[`water`,400,`ml`],[`white-granulated-sugar`,100,`g`],[`rose-water`,20,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`mozzarella`,320,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[[`heavy-cream`,250,`ml`],[`white-granulated-sugar`,45,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`pistachio`,70,`g`]]}];var h={slug:n,id:t,country:`SY`,region:s,servings:8,minutes:44,title:l,text:d,steps:g};export{a as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,d as text,l as title};